from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
DATA=(ROOT/'preuves/resultats.json').read_text(encoding='utf-8')
HTML='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'; base-uri 'none'; form-action 'none'"><title>BOJ.ART · laboratoire de planning</title><style>
:root{--ink:#eeeae2;--muted:#b5adad;--bg:#111217;--panel:#1b1c23;--line:#363640;--red:#db4b61;--gold:#efbe7c;--blue:#7fb2df}*{box-sizing:border-box}body{background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,sans-serif;margin:0}header{border-bottom:1px solid var(--line);padding:22px max(22px,calc((100vw - 1180px)/2));display:flex;gap:20px;align-items:center;justify-content:space-between}.brand{font-weight:900;letter-spacing:2px}.brand i{color:var(--red);font-style:normal}.badge{font-size:12px;padding:6px 11px;border-radius:20px;border:1px solid #70404d;color:#ffc7c7}main{max-width:1180px;margin:auto;padding:28px 22px 50px}h1{font-size:clamp(28px,4vw,42px);line-height:1.1;margin:12px 0}h2{font-size:20px}h3{font-size:16px}p{margin:12px 0}.muted{color:var(--muted)}.note{border-left:3px solid var(--gold);background:#27221e;padding:13px 16px;font-size:14px}.tabs{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0 18px}button{font:inherit;font-size:14px;color:var(--ink);background:#21222a;border:1px solid #5a525b;border-radius:8px;padding:10px 13px;cursor:pointer}button[aria-pressed=true]{background:#6d283b;border-color:#e76e81}button:focus-visible{outline:3px solid var(--gold);outline-offset:3px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card,.panel{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:18px}.card strong{display:block;font-size:25px;margin:8px 0}.card small{font-size:13px;color:var(--muted)}.panel{margin-top:18px}.scroll{overflow-x:auto}.chart{min-width:830px}.axis{display:flex;justify-content:space-between;margin:0 0 10px 185px;font-size:12px;color:var(--muted)}.row{display:grid;grid-template-columns:185px 1fr;min-height:45px;align-items:center;font-size:12px}.rowname{font-weight:650}.lane{position:relative;height:31px;background:repeating-linear-gradient(90deg,#15161a 0,#15161a calc(16.666% - 1px),#34353b calc(16.666% - 1px),#34353b 16.666%);border-radius:4px}.block{position:absolute;top:3px;height:25px;border-radius:3px;min-width:2px;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:4px 5px;color:#1e1519;transition:left .25s ease,width .25s ease}.block[data-job=SOCLE]{background:#8eb8d6}.block[data-job=TORSE]{background:#e57987}.block[data-job=DETAIL]{background:#e4bc84}.block[data-job=INDISPONIBLE]{background:repeating-linear-gradient(45deg,#666 0,#666 4px,#45454c 4px,#45454c 8px);color:white}.legend{display:flex;gap:18px;flex-wrap:wrap;font-size:13px;margin:14px 0}.swatch{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:6px}table{width:100%;min-width:630px;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:11px;border-bottom:1px solid var(--line)}th{font-size:12px;color:var(--muted);font-weight:500}.bottom{display:grid;grid-template-columns:1fr 1fr;gap:15px}.bottom .panel{font-size:14px}.empty{padding:40px 18px;border:1px dashed var(--red);border-radius:10px;color:#ffb8c1}.subtitle{font-size:12px;letter-spacing:.13em;color:#e68b99}.key{color:#f5c896}footer{border-top:1px solid var(--line);padding-top:18px;margin-top:26px;font-size:12px;color:var(--muted)}@media(max-width:700px){header{align-items:flex-start;flex-direction:column;padding:17px}.summary,.bottom{grid-template-columns:1fr}main{padding:22px 16px}.badge{font-size:11px}td,th{padding:10px 6px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
</style></head><body><header><div class="brand">BOJ<i>.</i>ART / JARVIS</div><div class="badge">LABORATOIRE · DONNÉES FICTIVES · HORS MACHINES</div></header><main><div class="subtitle">INNOVATION 03 · PLANIFIER UNE PIÈCE FINIE</div><h1>Ce n’est pas fini<br>quand l’imprimante s’arrête.</h1><p class="muted">Comparer une indisponibilité, une charge de finition et une échéance. Les résultats ci-dessous ont été calculés par un prototype Python indépendant.</p><div class="note"><b>Ce n’est ni le planning réel de BOJ.ART ni un délai client.</b> Durées inventées, trois dossiers d’exercice, aucune connexion. La recherche est heuristique : le meilleur plan trouvé n’est pas garanti optimal.</div><nav class="tabs" aria-label="Scénarios"><button data-case="base" aria-pressed="true">Situation de départ</button><button data-case="machine_absente" aria-pressed="false">Une résine indisponible</button><button data-case="finition_plus_longue" aria-pressed="false">Finition × 2</button><button data-case="echeance_courte" aria-pressed="false">Échéance courte</button><button data-case="compatibilite_manquante" aria-pressed="false">Compatibilité absente</button></nav><section aria-live="polite"><div class="summary"><div class="card"><small>ÉTAT DE LA SIMULATION</small><strong id="status"></strong><small id="explanation"></small></div><div class="card"><small>FIN DU PLAN TROUVÉ</small><strong id="end"></strong><small>Minutes après le début fictif du scénario.</small></div><div class="card"><small>EXÉCUTION PHYSIQUE</small><strong>Impossible ici</strong><small>Aucun connecteur, aucun ordre envoyé.</small></div></div><div class="panel"><h2 id="scenario"></h2><div class="legend"><span><i class="swatch" style="background:#8eb8d6"></i>Socle FDM</span><span><i class="swatch" style="background:#e57987"></i>Torse résine</span><span><i class="swatch" style="background:#e4bc84"></i>Détail résine</span><span>Grisé : indisponibilité</span></div><div class="scroll"><div id="schedule" class="chart"></div></div><p class="muted" style="font-size:13px">La réservation machine comprend préparation, impression, attente éventuelle et retrait. Survolez un segment pour voir son libellé. Sur téléphone, faites défiler le planning horizontalement.</p></div><div class="panel"><h2>Résultats par dossier</h2><div class="scroll"><table><thead><tr><th>DOSSIER</th><th>MACHINE</th><th>TERMINÉ À</th><th>ÉCHÉANCE FICTIVE</th><th>ÉCART DU PLAN</th></tr></thead><tbody id="rows"></tbody></table></div></div></section><div class="bottom"><div class="panel"><h2>Ce qui est testé</h2><p><span class="key">22 tests Python réussis.</span> Absence de chevauchement, opérateur indisponible, station lavage/cure commune, retrait différé, changement de scénario et refus d’affectation au mauvais procédé.</p><p>Les plans sont reproductibles et portent l’empreinte de leur scénario. Aucune commande de machine n’existe dans ce module.</p></div><div class="panel"><h2>Le raccordement envisagé</h2><p>Registre réel → profils et durées mesurées → solveur OR-Tools → présentation → validation → moteur d’exécution séparé.</p><p>OR-Tools a été étudié, mais n’a pas pu être installé dans cet environnement. Le prototype livré utilise uniquement Python et ne revendique pas son algorithme.</p></div></div><footer>BOJ.ART · 30 octobre 2026. Illustration technique, pas une recette de lavage/cure ni une validation de faisabilité d’une pièce. Sources et limites détaillées dans le dossier de recherche.</footer></main><script>const DATA=__DATA__;
const text=(id,value)=>document.getElementById(id).textContent=value;
function render(key){const r=DATA[key];text('scenario',r.scenario);const names={PLAN_FOUND:'Plan trouvé',PLAN_LATE:'Échéance dépassée',BLOCKED:'Bloqué',NO_PLAN_FOUND:'Pas de plan trouvé'};text('status',names[r.status]);text('explanation',r.status==='PLAN_LATE'?'Retard dans le meilleur plan trouvé, pas une preuve d’impossibilité.':r.status==='BLOCKED'?r.reason:'Simulation hors machines ; aucune capacité réelle établie.');text('end',r.score?r.score.completion_minutes+' min':'—');const sched=document.getElementById('schedule');sched.replaceChildren();const rows=document.getElementById('rows');rows.replaceChildren();if(!r.score){let e=document.createElement('div');e.className='empty';e.textContent=r.reason;sched.appendChild(e);let tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.textContent='Aucun plan à présenter.';tr.appendChild(td);rows.appendChild(tr);return;}let axis=document.createElement('div');axis.className='axis';for(let i=0;i<=6;i++){let e=document.createElement('span');e.textContent=(r.horizon*i/6)+' min';axis.appendChild(e)}sched.appendChild(axis);for(const [resource,spans] of Object.entries(r.reservations)){let row=document.createElement('div');row.className='row';let name=document.createElement('div');name.className='rowname';name.textContent=resource;let lane=document.createElement('div');lane.className='lane';for(const s of spans){let b=document.createElement('div');b.className='block';b.dataset.job=s.job;b.style.left=(s.start/r.horizon*100)+'%';b.style.width=((s.end-s.start)/r.horizon*100)+'%';b.title=`${s.job} · ${s.label} : ${s.start}–${s.end} min`;b.textContent=s.end-s.start>=50?s.job:'';lane.appendChild(b)}row.append(name,lane);sched.appendChild(row)}for(const x of r.results){let tr=document.createElement('tr');for(const val of [x.id,x.printer,x.complete+' min',x.due+' min',x.late_by?('+'+x.late_by+' min'):'Dans le plan']){let td=document.createElement('td');td.textContent=val;tr.appendChild(td)}rows.appendChild(tr)}}
document.querySelectorAll('button[data-case]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('button[data-case]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render(b.dataset.case)}));render('base');
</script></body></html>'''
(ROOT/'APERCU_PLANNING.html').write_text(HTML.replace('__DATA__',DATA.replace('</','<\\/')),encoding='utf-8')
